60	/**
61	 * @author Vitaliy Fedoriv
62	 */
63	
64	@RestController
65	@CrossOrigin(exposedHeaders = "errors, content-type")
66	@RequestMapping("/api")
67	public class OwnerRestControllerV1 implements OwnersApi {
68	
69	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
70	
71	    /**
72	     * The HTTP request header a client may send to make a create idempotent. When a create repeats
73	     * with a key already seen, the originally created owner is returned instead of a duplicate.
74	     */
75	    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";
76	
77	    /**
78	     * Remembers, per {@link #IDEMPOTENCY_KEY_HEADER Idempotency-Key}, the id of the owner that key's
79	     * first successful create produced, so a repeat of that create can return the same owner rather
80	     * than creating a duplicate.
81	     */
82	    private final Map<String, Integer> idempotentCreates = new ConcurrentHashMap<>();
83	
84	    /**
85	     * Fixed public-holiday calendar. A registration date that lands on one of these dates is rolled
86	     * forward to the next non-holiday business day, in the same way weekends are.
87	     */
88	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
89	        LocalDate.of(2026, 1, 1),
90	        LocalDate.of(2026, 1, 26),
91	        LocalDate.of(2026, 4, 25),
92	        LocalDate.of(2026, 12, 25),
93	        LocalDate.of(2026, 12, 28));
94	
95	    private final ClinicService clinicService;
96	
97	    private final OwnerMapper ownerMapper;
98	
99	    private final PetMapper petMapper;
100	
101	    private final VisitMapper visitMapper;
102	
103	    private final AddressNormalizer addressNormalizer;
104	
105	    public OwnerRestControllerV1(ClinicService clinicService,
106	                                 OwnerMapper ownerMapper,
107	                                 PetMapper petMapper,
108	                                 VisitMapper visitMapper,
109	                                 AddressNormalizer addressNormalizer) {
110	        this.clinicService = clinicService;
111	        this.ownerMapper = ownerMapper;
112	        this.petMapper = petMapper;
113	        this.visitMapper = visitMapper;
114	        this.addressNormalizer = addressNormalizer;
115	    }
116	
117	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
118	    @Override
119	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
120	        Collection<Owner> owners;
121	        if (lastName != null) {
122	            owners = this.clinicService.findOwnerByLastName(lastName);
123	        } else {
124	            owners = this.clinicService.findAllOwners();
125	        }
126	        if (owners.isEmpty()) {
127	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
128	        }
129	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
130	    }
131	
132	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
133	    @Override
134	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
135	        Owner owner = this.clinicService.findOwnerById(ownerId);
136	        if (owner == null) {
137	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
138	        }
139	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
140	    }
141	
142	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
143	    @Override
144	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
145	        String idempotencyKey = currentIdempotencyKey();
146	        if (idempotencyKey != null) {
147	            Integer existingId = idempotentCreates.get(idempotencyKey);
148	            if (existingId != null) {
149	                Owner existing = this.clinicService.findOwnerById(existingId);
150	                if (existing != null) {
151	                    return new ResponseEntity<>(ownerMapper.toOwnerDto(existing), HttpStatus.OK);
152	                }
153	            }
154	        }
155	
156	        ResponseEntity<OwnerDto> response = createOwner(ownerFieldsDto);
157	
158	        if (idempotencyKey != null && response.getStatusCode() == HttpStatus.CREATED
159	            && response.getBody() != null && response.getBody().getId() != null) {
160	            idempotentCreates.put(idempotencyKey, response.getBody().getId());
161	        }
162	        return response;
163	    }
164	
165	    /**
166	     * The non-blank {@link #IDEMPOTENCY_KEY_HEADER Idempotency-Key} header of the request currently
167	     * being handled, or {@code null} when the request carries no such header (or no request is bound
168	     * to the current thread). Used to make a repeated create return the originally created owner.
169	     */
170	    private String currentIdempotencyKey() {
171	        if (!(RequestContextHolder.getRequestAttributes() instanceof ServletRequestAttributes attributes)) {
172	            return null;
173	        }
174	        String key = attributes.getRequest().getHeader(IDEMPOTENCY_KEY_HEADER);
175	        return (key == null || key.isBlank()) ? null : key;
176	    }
177	
178	    /**
179	     * Run the full owner-creation pipeline for a submitted {@link OwnerFieldsDto} and build its
180	     * response. The submitted fields are mapped to an {@link Owner}, which is
181	     * {@link #normalizeAndValidate(Owner) normalized and validated}, checked against the
182	     * {@link #isDailyLimitReached(LocalDate) daily creation limit}, {@link #assignHousehold(Owner)
183	     * assigned its household} and screened for {@link #checkForConflicts(Owner) conflicts};
184	     * a surviving owner then has its {@link #assignDerivedAttributes(Owner, boolean) derived
185	     * attributes} assigned, is persisted and audited. Returns the {@link #created(Owner) 201 Created}
186	     * response for the persisted owner, or the {@link HttpStatus} the create must fail with
187	     * ({@code 400 Bad Request}, {@code 429 Too Many Requests} or {@code 409 Conflict}) when the owner
188	     * cannot be created.
189	     */
190	    private ResponseEntity<OwnerDto> createOwner(OwnerFieldsDto ownerFieldsDto) {
191	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
192	
193	        HttpStatus invalid = normalizeAndValidate(owner);
194	        if (invalid != null) {
195	            return new ResponseEntity<>(invalid);
196	        }
197	        if (isDailyLimitReached(owner.getRegistrationDate())) {
198	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
199	        }
200	
201	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
202	        assignHousehold(owner);
203	
204	        HttpStatus conflict = checkForConflicts(owner);
205	        if (conflict != null) {
206	            return new ResponseEntity<>(conflict);
207	        }
208	
209	        assignDerivedAttributes(owner, sharesHousehold);
210	        this.clinicService.saveOwner(owner);
211	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
212	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
213	            owner.getMembershipLevel(), owner.getMembershipNumber());
214	        return created(owner);
215	    }
216	
217	    /**
218	     * Bring a freshly mapped owner into its canonical, valid form, or report the reason it must be
219	     * rejected. The owner's {@link #normalizeAddress(Owner) address is normalized} (a missing address
220	     * is rejected), its telephone is converted to E.164 (an unconvertible number is rejected), its
221	     * postcode is checked against its city's region, a registration date in the future is rejected,
222	     * and the effective registration date (the supplied one, or today when none was given) is rolled
223	     * onto a business day and stored back on the owner. Returns {@code null} once the owner is valid
224	     * and normalized, or the {@link HttpStatus} the create must fail with ({@code 400 Bad Request})
225	     * otherwise.
226	     */
227	    private HttpStatus normalizeAndValidate(Owner owner) {
228	        if (!normalizeAddress(owner)) {
229	            return HttpStatus.BAD_REQUEST;
230	        }
231	        String telephone = toE164(owner.getTelephone());
232	        if (telephone == null) {
233	            return HttpStatus.BAD_REQUEST;
234	        }
235	        owner.setTelephone(telephone);
236	        if (isDisposableEmail(owner.getEmail())) {
237	            return HttpStatus.BAD_REQUEST;
238	        }
239	        if (!owner.isPostcodeValid()) {
240	            return HttpStatus.BAD_REQUEST;
241	        }
242	        if (owner.getRegistrationDate() != null
243	            && owner.getRegistrationDate().isAfter(LocalDate.now())) {
244	            return HttpStatus.BAD_REQUEST;
245	        }
246	        LocalDate effectiveDate = owner.getRegistrationDate() != null
247	            ? owner.getRegistrationDate() : LocalDate.now();
248	        owner.setRegistrationDate(toBusinessDay(effectiveDate));
249	        return null;
250	    }
251	
252	    /**
253	     * Normalize the owner's supplied address into its canonical stored form and report whether an
254	     * address was supplied at all. The owner may supply its address either as the structured
255	     * {@code addressLine1}/{@code addressLine2} fields or as the flat {@code address} field, which is
256	     * kept for backward compatibility; the structured form is preferred whenever a non-blank
257	     * {@code addressLine1} is present. Each supplied field is run through the {@link AddressNormalizer}
258	     * (trimmed, whitespace-collapsed, upper-cased, common street-type abbreviations expanded). When the
259	     * structured form is used, the normalized {@code addressLine1} and {@code addressLine2} are stored
260	     * back and the composed {@link Owner#getAddress() address} becomes the normalized
261	     * {@code addressLine1} with a single space and the normalized {@code addressLine2} appended when an
262	     * {@code addressLine2} is present; when the flat form is used, the normalized flat address is
263	     * stored and no structured lines are kept. Returns {@code true} once a non-blank address has been
264	     * normalized and stored, or {@code false} when neither form supplied an address, in which case the
265	     * create must be rejected with {@code 400 Bad Request}.
266	     */
267	    private boolean normalizeAddress(Owner owner) {
268	        String line1 = addressNormalizer.normalize(owner.getAddressLine1());
269	        if (!line1.isEmpty()) {
270	            String line2 = addressNormalizer.normalize(owner.getAddressLine2());
271	            owner.setAddressLine1(line1);
272	            owner.setAddressLine2(line2.isEmpty() ? null : line2);
273	            owner.setAddress(line2.isEmpty() ? line1 : line1 + " " + line2);
274	            return true;
275	        }
276	        String address = addressNormalizer.normalize(owner.getAddress());
277	        if (address.isEmpty()) {
278	            return false;
279	        }
280	        owner.setAddressLine1(null);
281	        owner.setAddressLine2(null);
282	        owner.setAddress(address);
283	        return true;
284	    }
285	
286	    /**
287	     * The set of disposable (throwaway) email domains that an owner's email may not use. An owner
288	     * whose email is hosted on one of these domains is rejected with {@code 400 Bad Request}.
289	     */
290	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS = Set.of(
291	        "mailinator.com", "tempmail.com", "guerrillamail.com");
292	
293	    /**
294	     * Whether the given email is hosted on a {@linkplain #DISPOSABLE_EMAIL_DOMAINS disposable}
295	     * domain. The email is optional, so a {@code null} or empty email is not disposable; otherwise
296	     * the domain (the part after the last {@code '@'}, compared case-insensitively) is matched
297	     * against the blocklist.
298	     */
299	    private boolean isDisposableEmail(String email) {
300	        if (email == null || email.isEmpty()) {
301	            return false;
302	        }
303	        int at = email.lastIndexOf('@');
304	        if (at < 0) {
305	            return false;
306	        }
307	        String domain = email.substring(at + 1).toLowerCase();
308	        return DISPOSABLE_EMAIL_DOMAINS.contains(domain);
309	    }
310	
311	    /**
312	     * Assign the owner its household link. The {@link #householdId(Owner) householdId} is computed
313	     * deterministically from the owner's lastName and postcode, so every owner sharing that
314	     * lastName and postcode is assigned the same value automatically, independent of whether the
315	     * owner declares it shares a household. The link is assigned before the
316	     * {@link #checkForConflicts(Owner) conflict checks} because it is part of the owner's
317	     * {@link Owner#getIdentityKey() identity} and feeds its {@link #householdSize(String) household
318	     * size}.
319	     */
320	    private void assignHousehold(Owner owner) {
321	        owner.setHouseholdId(householdId(owner));
322	    }
323	
324	    /**
325	     * Whether the owner clashes with an owner that already exists, and the {@link HttpStatus} the
326	     * create must fail with when it does. An owner is rejected with {@code 409 Conflict} only when
327	     * its {@link #isCityAtCapacity(String) city is already at capacity}. Sharing a household with
328	     * existing members is not a conflict: the owner is admitted as a household member and has its
329	     * {@linkplain #membershipLevel(Owner) membership level} capped at one above the household
330	     * maximum. Returns {@code null} when the owner clashes with nothing and may be created.
331	     */
332	    private HttpStatus checkForConflicts(Owner owner) {
333	        if (isCityAtCapacity(owner.getCity())) {
334	            return HttpStatus.CONFLICT;
335	        }
336	        return null;
337	    }
338	
339	    /**
340	     * Build the {@code 201 Created} response for a persisted owner: its {@link OwnerDto} body and a
341	     * {@code Location} header pointing at {@code /api/owners/{id}}.
342	     */
343	    private ResponseEntity<OwnerDto> created(Owner owner) {
344	        HttpHeaders headers = new HttpHeaders();
345	        headers.setLocation(UriComponentsBuilder.newInstance()
346	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
347	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), headers, HttpStatus.CREATED);
348	    }
349	
350	    /**
351	     * Assign the attributes that are derived once, at creation time, and stored on the owner: its
352	     * {@link #customerCode(Owner) customerCode}, {@link #namesakeCount(String, String) namesakeCount},
353	     * {@link #isBulkSignup(LocalDate) bulk-signup warning}, {@link #householdSize(String)
354	     * householdSize} and {@link #membershipLevel(Owner) membershipLevel}. Each is computed from the
355	     * owner's own fields together with the owners already present, so this runs after the owner has
356	     * been validated and has passed the duplicate and capacity checks, and immediately before it is
357	     * persisted.
358	     */
359	    private void assignDerivedAttributes(Owner owner, boolean sharesHousehold) {
360	        owner.setCustomerCode(customerCode(owner));
361	        owner.setNamesakeCount(namesakeCount(owner.getFirstName(), owner.getLastName()));
362	        owner.setBulkSignupWarning(isBulkSignup(owner.getRegistrationDate()));
363	        owner.setHouseholdSize(householdSize(owner.getHouseholdId()));
364	        owner.setMembershipLevel(membershipLevel(owner));
365	        assignPossibleDuplicate(owner, sharesHousehold);
366	    }
367	
368	    /**
369	     * The membership level to assign a newly created owner and store on it as its
370	     * {@link Owner#getMembershipLevel() membershipLevel}: the owner's own
371	     * {@linkplain Owner#getBaseMembershipLevel() base level} derived from its membershipPoints,
372	     * capped so it cannot exceed one above the current maximum membershipLevel among the owner's
373	     * existing {@linkplain #householdMembers(String) household members}. With no existing household
374	     * member no cap applies and the base level is used as-is. This is the single place the stored
375	     * membership level is derived; it runs during {@link #assignDerivedAttributes(Owner, boolean)},
376	     * after the owner has passed the duplicate and capacity checks and so has its household members
377	     * available to it.
378	     */
379	    private Integer membershipLevel(Owner owner) {
380	        int base = owner.getBaseMembershipLevel();
381	        Collection<Owner> members = householdMembers(owner.getHouseholdId());
382	        if (members.isEmpty()) {
383	            return base;
384	        }
385	        int householdMax = members.stream()
386	            .mapToInt(Owner::getMembershipLevel)
387	            .max()
388	            .getAsInt();
389	        return Math.min(base, householdMax + 1);
390	    }
391	
392	    /**
393	     * Flag a newly created owner as a possible (soft) duplicate. An owner that declares it shares a
394	     * household ({@code sharesHousehold}) is a declared household member, not a suspected duplicate,
395	     * so it is never flagged. Otherwise it is flagged only when it is a soft match of an existing
396	     * owner as determined by {@link #findSoftDuplicate(Owner)}. When such an owner exists the new owner is flagged with
397	     * {@code possibleDuplicate = true} and {@code possibleDuplicateOf} set to that owner's id;
398	     * otherwise {@code possibleDuplicate = false} and no matching id is recorded.
399	     */
400	    private void assignPossibleDuplicate(Owner owner, boolean sharesHousehold) {
401	        Owner match = sharesHousehold ? null : findSoftDuplicate(owner);
402	        owner.setPossibleDuplicate(match != null);
403	        owner.setPossibleDuplicateOf(match == null ? null : match.getId());
404	    }
405	
406	    /**
407	     * The owners a newly created owner is checked against by the duplicate and identity rules:
408	     * the {@link #householdMembers(String) household} membership and {@link #findSoftDuplicate(Owner)
409	     * soft-duplicate} checks, the {@link #customerCode(Owner) customerCode} de-duplication and the
410	     * {@link #namesakeCount(String, String) namesake} count. This is the single place that scope is
411	     * defined, so every one of those rules considers exactly the same set of owners; it spans every
412	     * owner the clinic holds except those flagged {@linkplain Owner#isDeleted() deleted}, which a
413	     * soft delete retains but excludes from duplicate and identity detection.
414	     */
415	    private Collection<Owner> activeOwners() {
416	        return this.clinicService.findAllOwners().stream()
417	            .filter(owner -> !owner.isDeleted())
418	            .collect(Collectors.toList());
419	    }
420	
421	    /**
422	     * The existing owner this owner softly duplicates, or {@code null} when there is none. A soft
423	     * match is an existing owner that shares this owner's lastName (compared case-insensitively,
424	     * with collapsed whitespace) and its postcode but carries a different telephone; the earliest
425	     * such owner (by id) is returned. A postcode is required for a soft match, so an owner without a
426	     * postcode never matches.
427	     */
428	    private Owner findSoftDuplicate(Owner owner) {
429	        if (owner.getPostcode() == null) {
430	            return null;
431	        }
432	        String candidateLastName = normalizeName(owner.getLastName());
433	        return activeOwners().stream()
434	            .filter(existing -> owner.getPostcode().equals(existing.getPostcode()))
435	            .filter(existing -> normalizeName(existing.getLastName()).equals(candidateLastName))
436	            .filter(existing -> !owner.getTelephone().equals(existing.getTelephone()))
437	            .min(Comparator.comparingInt(Owner::getId))
438	            .orElse(null);
439	    }
440	
441	    /**
442	     * Build the customer code for a newly created owner, formatted {@code '<REGION>-<HASH8>'}
443	     * where REGION is the region derived from the owner's postcode (or {@link Owner#UNKNOWN_REGION}
444	     * when the postcode is absent or maps to no known region) and HASH8 is the first 8 upper-case
445	     * hex characters of the SHA-256 of the normalized (E.164) telephone concatenated with the
446	     * lastName (e.g. {@code 'NSW-3C1A9F2B'}). This is the single source of the owner's identity:
447	     * every value built from the customer code (the membership number and its check digit) and the
448	     * owner's locality are derived from it.
449	     *
450	     * <p>When the computed code collides with an existing owner's {@code customerCode}, a
451	     * {@code '-<n>'} suffix is appended with the smallest {@code n} of 2 or more that makes the code
452	     * unique, and the de-duplicated code is returned.
453	     */
454	    private String customerCode(Owner owner) {
455	        String region = owner.getRegion() != null ? owner.getRegion() : Owner.UNKNOWN_REGION;
456	        String hash8 = shaHexUpper(owner.getTelephone() + owner.getLastName()).substring(0, 8);
457	        String base = region + "-" + hash8;
458	
459	        Set<String> existingCodes = activeOwners().stream()
460	            .map(Owner::getCustomerCode)
461	            .filter(Objects::nonNull)
462	            .collect(Collectors.toSet());
463	
464	        if (!existingCodes.contains(base)) {
465	            return base;
466	        }
467	        int n = 2;
468	        while (existingCodes.contains(base + "-" + n)) {
469	            n++;
470	        }
471	        return base + "-" + n;
472	    }
473	
474	    /**
475	     * Whether the per-day owner creation limit has been reached for the given business day, i.e.
476	     * 100 or more owners already carry that {@code registrationDate}. The day is the adjusted
477	     * (business-day) registration date of the owner being created, so owners are counted per
478	     * business day. When true, a new owner must be rejected with {@code 429 Too Many Requests}.
479	     */
480	    private boolean isDailyLimitReached(LocalDate day) {
481	        long count = this.clinicService.findAllOwners().stream()
482	            .filter(existing -> day.equals(existing.getRegistrationDate()))
483	            .count();
484	        return count >= 100;
485	    }
486	
487	    /**
488	     * Whether creating this owner pushes the day's total past the bulk-signup threshold, i.e.
489	     * more than 80 owners have already been created for the given business day. Counts the owners
490	     * already carrying that {@code registrationDate} (the same accumulation as the daily-limit
491	     * rule); when that count exceeds 80 the newly created owner is flagged with a bulk-signup
492	     * warning.
493	     */
494	    private boolean isBulkSignup(LocalDate day) {
495	        long count = this.clinicService.findAllOwners().stream()
496	            .filter(existing -> day.equals(existing.getRegistrationDate()))
497	            .count();
498	        return count > 80;
499	    }
500	
501	    /**
502	     * Roll a registration date forward onto a business day: when it falls on a Saturday, Sunday or a
503	     * listed public holiday, advance it to the next non-holiday weekday; an ordinary weekday is
504	     * returned unchanged.
505	     */
506	    private LocalDate toBusinessDay(LocalDate date) {
507	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY
508	            || date.getDayOfWeek() == DayOfWeek.SUNDAY
509	            || PUBLIC_HOLIDAYS.contains(date)) {
510	            date = date.plusDays(1);
511	        }
512	        return date;
513	    }
514	
515	    /**
516	     * Whether the given city has reached its owner capacity, i.e. it already contains 50 or
517	     * more owners. Cities are compared case-insensitively.
518	     */
519	    private boolean isCityAtCapacity(String city) {
520	        long count = this.clinicService.findAllOwners().stream()
521	            .filter(existing -> existing.getCity() != null && existing.getCity().equalsIgnoreCase(city))
522	            .count();
523	        return count >= 50;
524	    }
525	
526	    /**
527	     * The number of existing owners that already share the given firstName and lastName,
528	     * compared case-insensitively (and with surrounding whitespace trimmed and internal
529	     * whitespace runs collapsed). Counted over the owners present before this create.
530	     */
531	    private int namesakeCount(String firstName, String lastName) {
532	        String candidateFirstName = normalizeName(firstName);
533	        String candidateLastName = normalizeName(lastName);
534	        return (int) activeOwners().stream()
535	            .filter(existing -> normalizeName(existing.getFirstName()).equals(candidateFirstName)
536	                && normalizeName(existing.getLastName()).equals(candidateLastName))
537	            .count();
538	    }
539	
540	    /**
541	     * The number of members in this owner's household after this create: the count of existing
542	     * owners already carrying the same non-null {@code householdId} plus one for the owner being
543	     * created. An owner with no household ({@code householdId == null}) is a household of one.
544	     * Owners sharing a household are matched by their assigned {@code householdId}, so the count
545	     * does not depend on the order in which household members were created.
546	     */
547	    private int householdSize(String householdId) {
548	        if (householdId == null) {
549	            return 1;
550	        }
551	        long existing = this.clinicService.findAllOwners().stream()
552	            .filter(other -> householdId.equals(other.getHouseholdId()))
553	            .count();
554	        return (int) existing + 1;
555	    }
556	
557	    /**
558	     * Convert a raw telephone input to its E.164 representation, or {@code null} if it
559	     * cannot form a valid E.164 number.
560	     *
561	     * <p>A leading '+' and country code are kept when present; otherwise country code
562	     * '+61' is assumed and a single leading '0' is dropped from the national digits.
563	     * Spaces, dashes and brackets (indeed any non-digit) are stripped. The result must
564	     * carry 8 to 15 digits after the '+', and — for a recognised country calling code —
565	     * exactly the national-digit count that code requires (see
566	     * {@link Owner#hasValidNationalLength}); otherwise it is rejected as invalid.
567	     */
568	    private String toE164(String telephone) {
569	        if (telephone == null) {
570	            return null;
571	        }
572	        boolean hasCountryCode = telephone.trim().startsWith("+");
573	        String digits = telephone.replaceAll("\\D", "");
574	        String e164;
575	        if (hasCountryCode) {
576	            e164 = digits;
577	        } else {
578	            if (digits.startsWith("0")) {
579	                digits = digits.substring(1);
580	            }
581	            e164 = "61" + digits;
582	        }
583	        if (e164.length() < 8 || e164.length() > 15) {
584	            return null;
585	        }
586	        if (!Owner.hasValidNationalLength(e164)) {
587	            return null;
588	        }
589	        return "+" + e164;
590	    }
591	
592	    /**
593	     * The existing owners already registered in the household identified by {@code householdId}: the
594	     * {@linkplain #activeOwners() active owners} carrying that same non-null householdId. The owner
595	     * being created is not yet persisted, so it is never among them, and a {@code null} householdId
596	     * (an owner with no household) yields an empty collection. This is the single source of a
597	     * household's existing membership, shared by every rule keyed by an owner's household (the
598	     * {@link #membershipLevel(Owner) membership-level} derivation) so the set is never re-derived
599	     * elsewhere; like the other identity rules it ignores {@linkplain Owner#isDeleted() deleted}
600	     * owners.
601	     */
602	    private Collection<Owner> householdMembers(String householdId) {
603	        if (householdId == null) {
604	            return List.of();
605	        }
606	        return activeOwners().stream()
607	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
608	            .collect(Collectors.toList());
609	    }
610	
611	    /**
612	     * Normalize an owner's name for household comparison: trim, collapse internal whitespace runs
613	     * to a single space and lower-case. A null value normalizes to the empty string.
614	     */
615	    private String normalizeName(String value) {
616	        if (value == null) {
617	            return "";
618	        }
619	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
620	    }
621	
622	    /**
623	     * A stable shared identifier for the household an owner belongs to, derived deterministically
624	     * from its lastName and postcode. The lastName is normalized (case-insensitive,
625	     * whitespace-collapsed) before hashing, so every owner sharing the same lastName and postcode is
626	     * assigned the same value regardless of the order in which they are created. Formatted as the
627	     * first 12 upper-case hex characters of the SHA-256 of {@code '<normalizedLastName>|<postcode>'}
628	     * (an absent postcode contributes the empty string).
629	     */
630	    private String householdId(Owner owner) {
631	        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode();
632	        String key = normalizeName(owner.getLastName()) + "|" + postcode;
633	        return shaHexUpper(key).substring(0, 12);
634	    }
635	
636	    /**
637	     * The upper-case rendering of the {@linkplain HashUtils#sha256Hex(String) SHA-256 hex} of
638	     * {@code input} (two hex characters per digest byte, so 64 characters in all). Callers that
639	     * need a shorter opaque token take a prefix of the result (e.g. {@link #householdId} keeps the
640	     * first 12 characters and {@link #customerCode} keeps the first 8). The hashing itself lives in
641	     * {@link HashUtils} so the one implementation is shared with the owner's
642	     * {@link Owner#getIdentityKey() identity key}.
643	     */
644	    private String shaHexUpper(String input) {
645	        return HashUtils.sha256Hex(input).toUpperCase();
646	    }
647	
648	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
649	    @Override
650	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
651	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
652	        if (currentOwner == null) {
653	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
654	        }
655	        currentOwner.setAddress(ownerFieldsDto.getAddress());
656	        currentOwner.setCity(ownerFieldsDto.getCity());
657	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
658	        currentOwner.setLastName(ownerFieldsDto.getLastName());
659	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
660	        this.clinicService.saveOwner(currentOwner);
661	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
662	    }
663	
664	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
665	    @Transactional
666	    @Override
667	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
668	        Owner owner = this.clinicService.findOwnerById(ownerId);
669	        if (owner == null) {
670	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
671	        }
672	        this.clinicService.deleteOwner(owner);
673	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
674	    }
675	
676	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
677	    @Override
678	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
679	        Owner owner = this.clinicService.findOwnerById(ownerId);
680	        if (owner == null) {
681	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
682	        }
683	        HttpHeaders headers = new HttpHeaders();
684	        Pet pet = petMapper.toPet(petFieldsDto);
685	        owner.setId(ownerId);
686	        pet.setOwner(owner);
687	        pet.getType().setName(null);
688	        this.clinicService.savePet(pet);
689	        PetDto petDto = petMapper.toPetDto(pet);
690	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
691	            .buildAndExpand(pet.getId()).toUri());
692	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
693	    }
694	
695	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
696	    @Override
697	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
698	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
699	        if (currentOwner != null) {
700	            Pet currentPet = this.clinicService.findPetById(petId);
701	            if (currentPet != null) {
702	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
703	                currentPet.setName(petFieldsDto.getName());
704	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
705	                this.clinicService.savePet(currentPet);
706	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
707	            }
708	        }
709	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
710	    }
711	
712	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
713	    @Override
714	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
715	        HttpHeaders headers = new HttpHeaders();
716	        Visit visit = visitMapper.toVisit(visitFieldsDto);
717	        Pet pet = new Pet();
718	        pet.setId(petId);
719	        visit.setPet(pet);
720	        this.clinicService.saveVisit(visit);
721	        VisitDto visitDto = visitMapper.toVisitDto(visit);
722	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
723	            .buildAndExpand(visit.getId()).toUri());
724	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
725	    }
726	
727	
728	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
729	    @Override
730	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
731	        Owner owner = this.clinicService.findOwnerById(ownerId);
732	        if (owner != null) {
733	            Pet pet = owner.getPet(petId);
734	            if (pet != null) {
735	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
736	            }
737	        }
738	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
739	    }
740	}
