302	    /**
303	     * The owner's initials: the upper-cased first letters of firstName and lastName,
304	     * dot-separated with a trailing dot, e.g. {@code 'J.S.'}.
305	     */
306	    public String getInitials() {
307	        return Character.toUpperCase(this.getFirstName().charAt(0)) + "."
308	            + Character.toUpperCase(this.getLastName().charAt(0)) + ".";
309	    }
310	
311	    /**
312	     * The owner's membership number, formatted {@code '<customerCode>-M<YY>'} where YY is the
313	     * last two digits of the {@linkplain #getFiscalYear() fiscal year} of the
314	     * (business-day-adjusted) registrationDate, e.g. {@code 'NSW-3C1A9F2B-M27'}.
315	     */
316	    public String getMembershipNumber() {
317	        return this.customerCode + "-M" + String.format("%02d", fiscalYearOf(this.registrationDate) % 100);
318	    }
319	
320	    /**
321	     * The owner's fiscal year, formatted {@code 'FY<YY>'} where YY is the last two digits of the
322	     * {@linkplain #fiscalYearOf(LocalDate) fiscal year} of the (business-day-adjusted)
323	     * {@link #registrationDate}, e.g. {@code 'FY27'}. The fiscal year starts on 1 July and is
324	     * labelled by the calendar year in which it ends.
325	     */
326	    public String getFiscalYear() {
327	        return "FY" + String.format("%02d", fiscalYearOf(this.registrationDate) % 100);
328	    }
329	
330	    /**
331	     * The fiscal year that contains the given date, identified by the calendar year in which it
332	     * ends. The fiscal year starts on 1 July, so a date in July through December belongs to the
333	     * fiscal year ending in the following calendar year, while a date in January through June
334	     * belongs to the fiscal year ending in the same calendar year.
335	     */
336	    private static int fiscalYearOf(LocalDate date) {
337	        return date.getMonthValue() >= 7 ? date.getYear() + 1 : date.getYear();
338	    }
339	
340	    /**
341	     * The Luhn check digit (a single digit, {@code 0}-{@code 9}) computed over the decimal digits
342	     * contained in the owner's {@link #customerCode}.
343	     */
344	    public int getCheckDigit() {
345	        return luhnCheckDigit(this.customerCode);
346	    }
347	
348	    /**
349	     * The Luhn check digit (a single digit, {@code 0}-{@code 9}) over the decimal digits
350	     * contained in {@code value}. Reading the digits right to left, every second one is
351	     * doubled (subtracting 9 whenever doubling yields a value above 9); the transformed
352	     * digits are summed, and the check digit is the amount that must be added to that sum to
353	     * reach the next multiple of ten. Any non-digit character in {@code value} is ignored, so
354	     * the digit is taken over exactly the digits the string carries.
355	     */
356	    private static int luhnCheckDigit(String value) {
357	        int sum = 0;
358	        boolean doubling = true;
359	        for (int i = value.length() - 1; i >= 0; i--) {
360	            char c = value.charAt(i);
361	            if (c < '0' || c > '9') {
362	                continue;
363	            }
364	            int digit = c - '0';
365	            if (doubling) {
366	                digit *= 2;
367	                if (digit > 9) {
368	                    digit -= 9;
369	                }
370	            }
371	            sum += digit;
372	            doubling = !doubling;
373	        }
374	        return (10 - (sum % 10)) % 10;
375	    }
376	
377	    /** Fixed city-to-region table used to derive an owner's locality. */
378	    private static final Map<String, String> CITY_REGION = Map.of(
379	        "Sydney", "NSW",
380	        "Melbourne", "VIC",
381	        "Brisbane", "QLD");
382	
383	    /** The region reported for a city that is not present in {@link #CITY_REGION}. */
384	    public static final String UNKNOWN_REGION = "UNKNOWN";
385	
386	    /**
387	     * The canonical region for a city, derived from the fixed city-to-region table
388	     * ({@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD}), or
389	     * {@link #UNKNOWN_REGION} when the city is not in the table. This is the single
390	     * source of the city-to-region mapping, shared by every rule that is keyed by
391	     * region so the mapping is never re-derived elsewhere.
392	     */
393	    public static String regionOf(String city) {
394	        return CITY_REGION.getOrDefault(city, UNKNOWN_REGION);
395	    }
396	
397	    /**
398	     * The owner's locality: the {@code <REGION>} component of the {@link #getCustomerCode()
399	     * customerCode} (its prefix up to the first {@code '-'}), which is the region derived from
400	     * the owner's postcode at creation ({@link #UNKNOWN_REGION} when the postcode maps to no
401	     * known region). Locality is read from the region-and-hash identity so it never re-derives
402	     * a region of its own; it is {@link #UNKNOWN_REGION} for an owner that has no customerCode.
403	     */
404	    public String getLocality() {
405	        if (this.customerCode == null) {
406	            return UNKNOWN_REGION;
407	        }
408	        int dash = this.customerCode.indexOf('-');
409	        return dash < 0 ? this.customerCode : this.customerCode.substring(0, dash);
410	    }
411	
412	    /** Fixed region-to-timezone table, mapping a region to its IANA timezone name. */
413	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
414	        "NSW", "Australia/Sydney",
415	        "VIC", "Australia/Melbourne",
416	        "QLD", "Australia/Brisbane");
417	
418	    /**
419	     * The owner's timezone: the IANA name for this owner's {@linkplain #getLocality() locality},
420	     * looked up in the fixed region-to-timezone table ({@code NSW -> Australia/Sydney},
421	     * {@code VIC -> Australia/Melbourne}, {@code QLD -> Australia/Brisbane}), or {@code null} when
422	     * the locality maps to no known region (e.g. {@link #UNKNOWN_REGION}). It reads the locality
423	     * rather than re-deriving a region so the timezone shares the owner's single region identity.
424	     */
425	    public String getTimezone() {
426	        return REGION_TIMEZONE.get(getLocality());
427	    }
428	
429	    /**
430	     * The region derived from this owner's postcode alone: the region whose fixed
431	     * {@linkplain #REGION_POSTCODE_RANGE postcode range} contains the postcode, or {@code null}
432	     * when the postcode is absent, not four digits, or in no known range. This is the {@code <REGION>}
433	     * component built into the owner's customer code at creation and, through it, the source of the
434	     * owner's {@linkplain #getLocality() locality}. It is the single place a region is read from an
435	     * owner's postcode, so every rule keyed by the postcode-derived region shares one derivation.
436	     */
437	    public String getRegion() {
438	        return regionOfPostcode(this.postcode);
439	    }
440	
441	    /**
442	     * The region whose fixed {@linkplain #REGION_POSTCODE_RANGE postcode range} contains the
443	     * given postcode, or {@code null} when the postcode is {@code null}, not four digits, or in
444	     * no known range.
445	     */
446	    private static String regionOfPostcode(String postcode) {
447	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
448	            return null;
449	        }
450	        int value = Integer.parseInt(postcode);
451	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGE.entrySet()) {
452	            int[] range = entry.getValue();
453	            if (value >= range[0] && value <= range[1]) {
454	                return entry.getKey();
455	            }
456	        }
457	        return null;
458	    }
459	
460	    /**
461	     * Fixed inclusive 4-digit postcode ranges keyed by region, as {@code {low, high}}:
462	     * {@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}. A region not
463	     * listed here (i.e. {@link #UNKNOWN_REGION}) accepts any 4-digit postcode.
464	     */
465	    private static final Map<String, int[]> REGION_POSTCODE_RANGE = Map.of(
466	        "NSW", new int[] {2000, 2099},
467	        "VIC", new int[] {3000, 3099},
468	        "QLD", new int[] {4000, 4099});
469	
470	    /**
471	     * Whether this owner's postcode is acceptable for its city. Postcode is optional, so a
472	     * {@code null} postcode is accepted. When present it must be four digits and, for a city
473	     * whose {@linkplain #regionOf(String) region} is known, fall within that region's fixed
474	     * inclusive range ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}); a
475	     * city with no known region accepts any 4-digit postcode.
476	     */
477	    public boolean isPostcodeValid() {
478	        if (this.postcode == null) {
479	            return true;
480	        }
481	        if (!this.postcode.matches("[0-9]{4}")) {
482	            return false;
483	        }
484	        int[] range = REGION_POSTCODE_RANGE.get(regionOf(this.city));
485	        if (range == null) {
486	            return true;
487	        }
488	        int value = Integer.parseInt(this.postcode);
489	        return value >= range[0] && value <= range[1];
490	    }
491	
492	    /**
493	     * The national (subscriber) digit count required by each known country calling code, keyed by
494	     * the code's digits (without the leading {@code '+'}): {@code '+1'} carries 10 national digits
495	     * and {@code '+61'} carries 9. This is the single source of the country-calling-code table,
496	     * shared by every rule keyed by an E.164 number's country code so the mapping is never
497	     * re-derived elsewhere.
498	     */
499	    private static final Map<String, Integer> NATIONAL_DIGITS_BY_COUNTRY = Map.of(
500	        "1", 10,
501	        "61", 9);
502	
503	    /**
504	     * The country calling code (its digits, without the leading {@code '+'}) that prefixes the given
505	     * E.164 digit string, choosing the longest matching code known to
506	     * {@link #NATIONAL_DIGITS_BY_COUNTRY}, or {@code null} when the number begins with no known
507	     * country code. This is the single place a country code is read from an E.164 number, so every
508	     * rule keyed by that code shares one derivation.
509	     */
510	    private static String countryCodeOf(String e164Digits) {
511	        return NATIONAL_DIGITS_BY_COUNTRY.keySet().stream()
512	            .filter(e164Digits::startsWith)
513	            .max(Comparator.comparingInt(String::length))
514	            .orElse(null);
515	    }
516	
517	    /**
518	     * Whether the E.164 digit string (no leading {@code '+'}) carries the national-number length
519	     * required by its {@linkplain #countryCodeOf(String) country calling code}. The longest matching
520	     * known code wins; a number whose country code is not recognised passes this check (its length is
521	     * then governed only by the general E.164 bound), while a recognised code must be followed by
522	     * exactly the national-digit count it requires ({@code '+1'} 10, {@code '+61'} 9).
523	     */
524	    public static boolean hasValidNationalLength(String e164Digits) {
525	        String countryCode = countryCodeOf(e164Digits);
526	        if (countryCode == null) {
527	            return true;
528	        }
529	        return e164Digits.length() - countryCode.length() == NATIONAL_DIGITS_BY_COUNTRY.get(countryCode);
530	    }
531	
532	    /**
533	     * The owner's membership points: they start at 0, gain 2 when an email is present, gain 1 when
534	     * namesakeCount is 0, gain 2 for a {@linkplain #hasLargeHousehold() household of 3 or more}, and
535	     * gain 3 when the owner's {@linkplain #getTenureFiscalYears() tenure} spans at least one
536	     * elapsed fiscal year. The email, namesake and household factors are available on creation; the
537	     * tenure factor is reached only once at least one fiscal-year boundary has passed.
538	     */
539	    public Integer getMembershipPoints() {
540	        int points = 0;
541	        if (hasEmail()) {
542	            points += 2;
543	        }
544	        if (hasNoNamesakes()) {
545	            points += 1;
546	        }
547	        if (hasLargeHousehold()) {
548	            points += 2;
549	        }
550	        if (hasQualifyingTenure()) {
551	            points += 3;
552	        }
553	        return points;
554	    }
555	
556	    /**
557	     * The owner's membership level, a number from 1 to 4. For an owner created through the
558	     * creation pipeline this is the value assigned and stored at creation time; an owner that
559	     * carries no assigned level (e.g. seed data, or an owner not created through that pipeline)
560	     * reports its {@linkplain #getBaseMembershipLevel() base level} derived from its
561	     * membershipPoints. This is the single value read by the API for an owner's membership level.
562	     */
563	    public Integer getMembershipLevel() {
564	        return this.membershipLevel != null ? this.membershipLevel : getBaseMembershipLevel();
565	    }
566	
567	    public void setMembershipLevel(Integer membershipLevel) {
568	        this.membershipLevel = membershipLevel;
569	    }
570	
571	    /**
572	     * The owner's base membership level, a number from 1 to 4 derived directly from
573	     * {@linkplain #getMembershipPoints() membershipPoints}: level 1 for 0-1 points, level 2 for 2-3,
574	     * level 3 for 4-5, and level 4 for 6 or more. This is the level the creation pipeline starts
575	     * from when it assigns the owner's stored {@linkplain #getMembershipLevel() membershipLevel}.
576	     */
577	    public Integer getBaseMembershipLevel() {
578	        int points = getMembershipPoints();
579	        if (points >= 6) {
580	            return 4;
581	        }
582	        if (points >= 4) {
583	            return 3;
584	        }
585	        if (points >= 2) {
586	            return 2;
587	        }
588	        return 1;
589	    }
590	
591	    /**
592	     * Whether this owner belongs to a household of three or more: its {@link #getHouseholdSize()
593	     * householdSize} is {@code 3} or greater. A {@code null} householdSize, meaning the size is not
594	     * known, is treated as not a large household.
595	     */
596	    private boolean hasLargeHousehold() {
597	        return this.householdSize != null && this.householdSize >= 3;
598	    }
599	
600	    /**
601	     * Whether this owner has an email on record: a non-{@code null}, non-empty {@link #getEmail()
602	     * email}. This is the single source of the "has an email" test, shared by every rule keyed by
603	     * email presence so the check is never re-derived elsewhere.
604	     */
605	    private boolean hasEmail() {
606	        return this.email != null && !this.email.isEmpty();
607	    }
608	
609	    /**
610	     * Whether this owner's name is unique in the clinic: its {@link #getNamesakeCount() namesakeCount}
611	     * is {@code 0} (no other owner shares the name). A {@code null} namesakeCount, meaning the count is
612	     * not known, is treated as not unique.
613	     */
614	    private boolean hasNoNamesakes() {
615	        return this.namesakeCount != null && this.namesakeCount == 0;
616	    }
617	
618	    /**
619	     * Whether this owner's {@linkplain #getTenureFiscalYears() tenure} spans at least one elapsed
620	     * fiscal year. A newly created owner (zero elapsed fiscal years) does not qualify; the threshold
621	     * is crossed only once at least one fiscal-year boundary has passed since registration.
622	     */
623	    private boolean hasQualifyingTenure() {
624	        return this.getTenureFiscalYears() >= 1;
625	    }
626	
627	    /**
628	     * The owner's tenure in elapsed fiscal years: the number of fiscal-year boundaries between the
629	     * {@linkplain #fiscalYearOf(LocalDate) fiscal year} of the {@link #registrationDate} and the
630	     * fiscal year of the current date, or {@code 0} when the registrationDate is not yet set (a newly
631	     * created owner has zero tenure). Never negative.
632	     */
633	    public long getTenureFiscalYears() {
634	        if (this.registrationDate == null) {
635	            return 0;
636	        }
637	        return Math.max(0, fiscalYearOf(LocalDate.now()) - fiscalYearOf(this.registrationDate));
638	    }
639	
640	    /**
641	     * The owner's preferred contact channel: {@code 'EMAIL'} when an email is present,
642	     * otherwise {@code 'PHONE'}.
643	     */
644	    public String getContactPreference() {
645	        return hasEmail() ? "EMAIL" : "PHONE";
646	    }
647	
648	    /**
649	     * The owner's stored E.164 {@linkplain #getTelephone() telephone} formatted for humans:
650	     * a {@code '+'}, the {@linkplain #countryCodeOf(String) country calling code}, a space, and
651	     * the national digits grouped into threes from the left separated by spaces,
652	     * e.g. {@code '+61412345678'} -> {@code '+61 412 345 678'}. The raw {@link #getTelephone()
653	     * telephone} stays in E.164. Returns the telephone unchanged when it is {@code null}, not in
654	     * E.164 form, or carries no known country code.
655	     */
656	    public String getTelephoneDisplay() {
657	        if (this.telephone == null || !this.telephone.startsWith("+")) {
658	            return this.telephone;
659	        }
660	        String digits = this.telephone.substring(1);
661	        String countryCode = countryCodeOf(digits);
662	        if (countryCode == null) {
663	            return this.telephone;
664	        }
665	        String national = digits.substring(countryCode.length());
666	        StringBuilder groups = new StringBuilder();
667	        for (int i = 0; i < national.length(); i += 3) {
668	            if (groups.length() > 0) {
669	                groups.append(' ');
670	            }
671	            groups.append(national, i, Math.min(i + 3, national.length()));
672	        }
673	        return "+" + countryCode + " " + groups;
674	    }
675	
676	    /**
677	     * The owner's identity key: the single derived value used for duplicate detection.
678	     * It joins the normalized (E.164) telephone, the email (already lower-cased, or the
679	     * empty string when absent) and the householdId (or the empty string when the owner
680	     * has no household) with {@code '|'}, e.g. {@code '+61412345678|jane@example.test|3C1A9F2B7D4E'}.
681	     * Two owners are duplicates only when their whole identity keys are equal.
682	     */
683	    public String getIdentityKey() {
684	        String telephonePart = this.telephone == null ? "" : this.telephone;
685	        String emailPart = this.email == null ? "" : this.email;
686	        String householdPart = this.householdId == null ? "" : this.householdId;
687	        return telephonePart + "|" + emailPart + "|" + householdPart;
688	    }
689	
690	    protected Set<Pet> getPetsInternal() {
691	        if (this.pets == null) {
692	            this.pets = new HashSet<>();
693	        }
694	        return this.pets;
695	    }
696	
697	    protected void setPetsInternal(Set<Pet> pets) {
698	        this.pets = pets;
699	    }
700	
701	    public List<Pet> getPets() {
702	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
703	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
704	        return Collections.unmodifiableList(sortedPets);
705	    }
706	
707	    public void setPets(List<Pet> pets) {
708	        this.pets = new HashSet<>(pets);
709	    }
710	
711	    public void addPet(Pet pet) {
712	        getPetsInternal().add(pet);
713	        pet.setOwner(this);
714	    }
715	
716	    /**
717	     * Return the Pet with the given name, or null if none found for this Owner.
718	     *
719	     * @param name to test
720	     * @return true if pet name is already in use
721	     */
722	    public Pet getPet(String name) {
723	        return getPet(name, false);
724	    }
725	
726	    /**
727	     * Return the Pet with the given name, or null if none found for this Owner.
728	     *
729	     * @param name to test
730	     * @return true if pet name is already in use
731	     */
732	    public Pet getPet(String name, boolean ignoreNew) {
733	        name = name.toLowerCase();
734	        for (Pet pet : getPetsInternal()) {
735	            if (!ignoreNew || !pet.isNew()) {
736	                String compName = pet.getName();
737	                compName = compName.toLowerCase();
738	                if (compName.equals(name)) {
739	                    return pet;
740	                }
741	            }
742	        }
743	        return null;
744	    }
745	
746	    public Pet getPet(Integer petId) {
747	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
748	    }
749	
750	    @Override
751	    public String toString() {
752	        return new ToStringCreator(this)
753	
754	            .append("id", this.getId())
755	            .append("new", this.isNew())
756	            .append("lastName", this.getLastName())
757	            .append("firstName", this.getFirstName())
758	            .append("address", this.address)
759	            .append("city", this.city)
760	            .append("telephone", this.telephone)
761	            .append("email", this.email)
762	            .toString();
763	    }
764	}
